    int sum = matrix.get(i).get(j);
    matrix.get(i).set(j, 0);

    LinkedList<int[]> stack = new LinkedList<>();
    stack.add(new int[] {i, j});

    while (stack.size() > 0) {
      int[] pos = stack.removeLast();
      int x = pos[0], y = pos[1];

